func writeZip(t *testing.T, files map[string][]byte) []byte {
	t.Helper()
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	for name, data := range files {
		w, err := zw.Create(name)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := w.Write(data); err != nil {
			t.Fatal(err)
		}
	}
	if err := zw.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func collect(t *testing.T, root string) map[string]Summary {
	t.Helper()
	got := map[string]Summary{}
	err := Walk(root, func(src Source, r io.Reader) error {
		s, err := Parse(r)
		if err != nil {
			return err
		}
		got[src.Path] = s
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return got
}

// TestWalkGarminExportLayout mimics the bulk export: an outer ZIP containing
// UploadedFiles_*.zip parts with the original FIT files.
func TestWalkGarminExportLayout(t *testing.T) {
	ride := encode(t, defaultFixture())
	other := defaultFixture()
	other.serial = 1
	ride2 := encode(t, other)

	inner := writeZip(t, map[string][]byte{
		"user@example.com_12345678901.fit": ride,
		"user@example.com_12345678902.fit": ride2,
		"readme.txt":                       []byte("ignored"),
	})
	outer := writeZip(t, map[string][]byte{
		"DI_CONNECT/DI-Connect-Uploaded-Files/UploadedFiles_0-_Part1.zip": inner,
		"DI_CONNECT/DI-Connect-Fitness/summarizedActivities.json":         []byte("{}"),
	})

	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "export.zip"), outer, 0o600); err != nil {
		t.Fatal(err)
	}
	// The same recording again as a loose file, e.g. copied via USB.
	if err := os.WriteFile(filepath.Join(dir, "2026-05-01-08-00-00.fit"), ride, 0o600); err != nil {
		t.Fatal(err)
	}

	got := collect(t, dir)
	if len(got) != 3 {
		t.Fatalf("found %d FIT files, want 3: %v", len(got), keys(got))
	}

	byKey := map[string][]string{}
	for path, s := range got {
		byKey[s.Key] = append(byKey[s.Key], path)
	}
	if len(byKey) != 2 {
		t.Errorf("want 2 distinct recordings, got %d: %v", len(byKey), byKey)
	}
}

func TestSourceActivityIDHint(t *testing.T) {
	for path, want := range map[string]string{
		"x.zip!user@example.com_12345678901.fit": "12345678901",
		"x.zip!12345678901_ACTIVITY.fit":         "12345678901",
		"2026-05-01-08-00-00.fit":                "",
		"ride.FIT":                               "",
	} {
		if got := newSource(path).GarminActivityID; got != want {
			t.Errorf("%s: id %q, want %q", path, got, want)
		}
	}
}

func keys(m map[string]Summary) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}
